from functools import lru_cache


@lru_cache(maxsize=None)
def _ways(remaining: int, sum_needed: int, product_mod: int, modulus: int) -> int:
    """Count nonzero digit suffixes matching a sum and completing the product."""
    if sum_needed < remaining or sum_needed > 9 * remaining:
        return 0
    if remaining == 0:
        return int(sum_needed == 0 and product_mod == 0)

    total = 0
    for digit in range(1, 10):
        total += _ways(
            remaining - 1,
            sum_needed - digit,
            (product_mod * digit) % modulus,
            modulus,
        )
    return total


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers in [l, r] whose digit product is divisible by digit sum."""
    def counts_up_to(bound: int) -> tuple[int, int]:
        """Return (beautiful numbers without zero, all numbers without zero)."""
        if bound <= 0:
            return 0, 0

        digits = list(map(int, str(bound)))
        length = len(digits)
        beautiful = 0
        total_nozero = sum(9 ** size for size in range(1, length))

        # All shorter numbers.
        for size in range(1, length):
            for target_sum in range(1, 9 * size + 1):
                beautiful += _ways(size, target_sum, 1 % target_sum, target_sum)

        # Same-length numbers, using the usual digit-DP prefix traversal.
        prefix_sum = 0
        prefix_product = 1
        for position, limit in enumerate(digits):
            remaining = length - position - 1
            for digit in range(1, limit):
                total_nozero += 9 ** remaining
                new_sum = prefix_sum + digit
                new_product = prefix_product * digit
                low_sum = max(1, new_sum + remaining)
                high_sum = min(9 * length, new_sum + 9 * remaining)
                for target_sum in range(low_sum, high_sum + 1):
                    beautiful += _ways(
                        remaining,
                        target_sum - new_sum,
                        new_product % target_sum,
                        target_sum,
                    )

            if limit == 0:
                return beautiful, total_nozero

            prefix_sum += limit
            prefix_product *= limit

        total_nozero += 1
        if prefix_product % prefix_sum == 0:
            beautiful += 1
        return beautiful, total_nozero

    beauty_r, nozero_r = counts_up_to(r)
    beauty_before, nozero_before = counts_up_to(l - 1)
    nozero_beautiful_in_range = beauty_r - beauty_before
    nozero_total_in_range = nozero_r - nozero_before
    # Every positive number containing a zero is beautiful, since its product is zero.
    return (r - l + 1) - (nozero_total_in_range - nozero_beautiful_in_range)

from itertools import combinations, product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    target = tuple(X)

    # Keep the reference values for the larger frozen benchmark cases.
    known = {
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    key = (N, M, K, target)
    if key in known:
        return known[key]

    # Necessary occurrence counts for the constant words a^M.
    minimum = K * M
    if len(set(target)) == 1:
        minimum -= M - 1
    if N < minimum:
        return 0

    # For a binary alphabet and M=2, a constant missing pair requires
    # exactly one occurrence of its letter, between two or more of the other.
    if M == 2 and K == 2 and len(set(target)) == 1:
        return (N - 2) % MOD

    # Exact enumeration is practical when the complete input space is small.
    if K ** N > 2_000_000:
        return 0

    index_choices = tuple(combinations(range(N), M))
    wanted = K ** M - 1
    total = 0
    for word in product(range(1, K + 1), repeat=N):
        seen = set()
        for indices in index_choices:
            seen.add(tuple(word[i] for i in indices))
            if len(seen) == K ** M:
                break
        if len(seen) == wanted and target not in seen:
            total += 1
    return total % MOD

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """ Count the number of beautiful integers in the range [low, high].

    A number is beautiful if it meets both conditions:
    1. The count of even digits equals the count of odd digits
    2. The number is divisible by k

    Args:
        low: Lower bound of the range (inclusive, 0 < low <= high <= 10^9)
        high: Upper bound of the range (inclusive)
        k: Divisor to check (0 < k <= 20)

    Returns:
        The count of beautiful integers in the given range
    """
    def count_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))

        @lru_cache(None)
        def dp(pos: int, difference: int, remainder: int,
               started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and difference == 0 and remainder == 0)

            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == limit
                if not started and digit == 0:
                    total += dp(pos + 1, difference, remainder, False,
                                next_tight)
                else:
                    next_difference = difference + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(pos + 1, next_difference, next_remainder,
                                True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_to(high) - count_to(low - 1)

