def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions inside the rectangle."""
    def local_area(x0, x1, y0, y1):
        # Integral over a small rectangle, using the periodic color rule.
        if x0 == x1 or y0 == y1:
            return 0.0
        cuts = {x0, x1}
        for k in range(int(x0) - 2, int(x1) + 3):
            if x0 < k < x1:
                cuts.add(float(k))
        # A diagonal y = 2k - x can change its relation to either
        # horizontal edge only at these x coordinates.
        for k in range(-4, 8):
            for edge in (y0, y1):
                xx = 2 * k - edge
                if x0 < xx < x1:
                    cuts.add(xx)
        xs = sorted(cuts)

        def black_length(x):
            ys = {y0, y1}
            for k in range(-4, 8):
                yy = 2 * k
                if y0 < yy < y1:
                    ys.add(float(yy))
                yy = 2 * k - x
                if y0 < yy < y1:
                    ys.add(yy)
            ordered = sorted(ys)
            total = 0.0
            for lo, hi in zip(ordered, ordered[1:]):
                ym = (lo + hi) / 2
                xm = x
                # Avoid evaluating exactly on a vertical boundary.
                if abs(xm - round(xm)) < 1e-12:
                    xm += 1e-9
                parity = (int(xm // 1) + int(ym // 2) + int((xm + ym) // 2)) & 1
                if parity == 0:
                    total += hi - lo
            return total

        area = 0.0
        for xa, xb in zip(xs, xs[1:]):
            area += (black_length(xa) + black_length(xb)) * (xb - xa) / 2
        return area

    def prefix(x, y):
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 4)
        tile = local_area(0, 4, 0, 4)
        vertical = local_area(0, 4, 0, ry)
        horizontal = local_area(0, rx, 0, 4)
        corner = local_area(0, rx, 0, ry)
        return qx * qy * tile + qx * vertical + qy * horizontal + corner

    return round(2 * (prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)))

