from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        total = 0

        # The digit sum is at most 9 * len(digits). For a fixed sum,
        # track the product modulo that sum in a small digit DP.
        for target_sum in range(1, 9 * len(digits) + 1):
            @lru_cache(maxsize=None)
            def dp(pos: int, digit_sum: int, product_mod: int, started: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if digit_sum + 9 * (len(digits) - pos) < target_sum:
                    return 0
                if pos == len(digits):
                    return int(started and digit_sum == target_sum and product_mod == 0)

                limit = digits[pos]
                # Tightness is represented by choosing the limit digit only while
                # the prefix still equals the bound. Encode it as an outer DP below.
                return 0

            # Include the tight flag in the state; this version keeps leading zeroes
            # out of the digit product until the first nonzero digit.
            @lru_cache(maxsize=None)
            def visit(pos: int, digit_sum: int, product_mod: int, started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if digit_sum + 9 * (len(digits) - pos) < target_sum:
                    return 0
                if pos == len(digits):
                    return int(started and digit_sum == target_sum and product_mod == 0)
                hi = digits[pos] if tight else 9
                ways = 0
                for digit in range(hi + 1):
                    next_started = started or digit != 0
                    next_sum = digit_sum + digit
                    if not next_started:
                        next_mod = 0
                    elif not started:
                        next_mod = digit % target_sum
                    else:
                        next_mod = (product_mod * digit) % target_sum
                    ways += visit(
                        pos + 1,
                        next_sum,
                        next_mod,
                        next_started,
                        tight and digit == hi,
                    )
                return ways

            total += visit(0, 0, 0, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

