                continue
            if is_h:
                if dx:
                    required = 0 if dx > 0 else K - 1
                    yield (ni, nj, required), 1
                else:
                    required = K - 1 if dy > 0 else 0
                    if k == required:
                        for q in values:
                            yield (ni, nj, q), 1
            else:
                if dx:
                    required = K - 1 if dx > 0 else 0
                    if k == required:
                        for q in values:
                            yield (ni, nj, q), 1
                else:
                    required = 0 if dy > 0 else K - 1
                    yield (ni, nj, required), 1

