def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the AtCoder wallpaper pattern."""
    def partial(u: int, v: int) -> int:
        # Integrate the black vertical length in one 2-by-2 period.
        cuts = sorted({0, u, min(u, 1), max(0, min(u, 2 - v)), min(u, 2)})
        cuts = [z for z in cuts if 0 <= z <= u]

        def length(x: int) -> int:
            diagonal_y = max(0, 2 - x)
            if x < 1:
                return max(0, min(v, diagonal_y))
            return max(0, v - min(v, diagonal_y))

        area2 = 0
        for left, right in zip(cuts, cuts[1:]):
            area2 += (length(left) + length(right)) * (right - left)
        return area2

    def prefix(x: int, y: int) -> int:
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 2)
        # Full-period black area is 2, so its doubled value is 4.
        # The one-dimensional strips have black fractions determined by
        # the same alternating triangle pattern.
        strip_x = partial(2, ry)
        strip_y = partial(rx, 2)
        return 4 * qx * qy + qx * strip_x + qy * strip_y + partial(rx, ry)

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)

